import{_ as s,o as t,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Bibliothèque d’icônes ATLAS","description":"Rechercher des jeux d’icônes Home Assistant, les parcourir et copier leurs noms.","frontmatter":{"title":"Bibliothèque d’icônes ATLAS","description":"Rechercher des jeux d’icônes Home Assistant, les parcourir et copier leurs noms."},"headers":[],"relativePath":"fr/projects/atlas-plugins/icon-library.md","filePath":"fr/projects/atlas-plugins/icon-library.md","lastUpdated":1793125707000}'),o={name:"fr/projects/atlas-plugins/icon-library.md"};function a(r,e,c,l,u,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="bibliotheque-d-icones-atlas" tabindex="-1">Bibliothèque d’icônes ATLAS <a class="header-anchor" href="#bibliotheque-d-icones-atlas" aria-label="Permalink to &quot;Bibliothèque d’icônes ATLAS&quot;">​</a></h1><p>La Bibliothèque d’icônes ATLAS est un plugin autonome qui permet de rechercher et de parcourir des jeux d’icônes. Les icônes sont affichées dans une grille de 20 colonnes au maximum ; pour les grands jeux, l’interface ne rend que la partie visible. Cliquez sur une icône pour copier son nom complet, par exemple <code>mdi:home</code> ou <code>atlas:home</code>.</p><p>Le catalogue MDI est inclus dans le plugin et le champ source l’identifie comme une source intégrée, et non comme un chemin de fichier Home Assistant. Par défaut, les icônes SVG utilisent la couleur d’accent et l’interface suit le thème clair ou sombre du navigateur.</p><h2 id="charger-des-jeux-d-icones" tabindex="-1">Charger des jeux d’icônes <a class="header-anchor" href="#charger-des-jeux-d-icones" aria-label="Permalink to &quot;Charger des jeux d’icônes&quot;">​</a></h2><p>Depuis la version 0.1.9, les changements de taille de la grille sont regroupés pour éviter une rétroaction ResizeObserver observée dans WebKit. L’affichage incomplet dans une VM Ventura avec Safari 16.6 n’est pas encore confirmé comme corrigé. Les jeux d’icônes enregistrés sont conservés.</p><p>Le paquet du plugin inclut le catalogue MDI. Les collections Icon Studio et les jeux d’icônes statiques Home Assistant compatibles peuvent être importés depuis l’ordinateur sous forme de fichiers JavaScript ou chargés depuis <code>/config/www/</code> avec File Studio. Le scanner parcourt également les sous-dossiers, notamment <code>/config/www/community/</code> (accessible dans Home Assistant sous <code>/local/community/</code>). Il recherche les jeux d’icônes JavaScript compatibles lorsque le nom du fichier ou d’un dossier contient « icon », puis regroupe ceux qui utilisent le même préfixe. Il prend notamment en charge Hue, Selfh.st, BHA, Yandex, Custom Icons, KNX, Thermal Comfort et Custom Brand Icons. Les fichiers JavaScript sont analysés comme des données et ne sont jamais exécutés. Les collections importées sont enregistrées localement dans le navigateur.</p><p>Certains anciens jeux d’icônes Home Assistant exposent leurs noms via <code>window.customIcons</code> et peuvent être affichés ainsi. La nouvelle interface <code>window.customIconsets</code> ne fournit pas de mécanisme général pour lister tous les noms d’un jeu quelconque. Ces jeux ne peuvent être affichés que s’ils fournissent également une liste de noms lisible.</p><p>File Studio doit autoriser l’accès à <code>/config/www/</code>. Le plugin n’a pas besoin d’un jeton Home Assistant pour cet accès.</p><h2 id="installation-et-code-source" tabindex="-1">Installation et code source <a class="header-anchor" href="#installation-et-code-source" aria-label="Permalink to &quot;Installation et code source&quot;">​</a></h2><p>Ajoutez ce dépôt externe dans le gestionnaire de plugins ATLAS :</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://raw.githubusercontent.com/rockbaer2007/atlas-icon-library-plugin/main/repository.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>ATLAS 0.1.248 ou une version ultérieure est requis, car cette version corrige l’installation des paquets externes.</p><p>Consultez le <a href="https://github.com/rockbaer2007/atlas-icon-library-plugin" target="_blank" rel="noreferrer">dépôt GitHub</a> pour le code source et les instructions de développement.</p>',13)])])}const h=s(o,[["render",a]]);export{m as __pageData,h as default};
